<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import DataGrid, { type GridColumn } from "@/components/DataGrid.vue";
import { ApiError } from "@/services/http";
import { useAuthSession } from "@/composables/useAuthSession";
import { downloadDetailedReport, downloadReportSummary, getReportOptions, getReportSummary, listAssignmentReport, listBeneficiaryReport, listCardReport, listHistoryReport, listRequestReport, type AssignmentReport, type BeneficiaryReport, type CardReport, type DetailedReportType, type HistoryReport, type Paginated, type ReportFilter, type ReportOptions, type ReportSummary, type RequestReport } from "@/services/reportes";

type Tab = "summary" | "beneficiarios" | "solicitudes" | "tarjetas" | "asignaciones" | "historial";
const tabs: Array<{ id: Tab; label: string }> = [{ id: "summary", label: "Resumen general" }, { id: "beneficiarios", label: "Beneficiarios" }, { id: "solicitudes", label: "Solicitudes" }, { id: "tarjetas", label: "Tarjetas" }, { id: "asignaciones", label: "Asignaciones y vigencias" }, { id: "historial", label: "Historial" }];
const auth = useAuthSession();
const canExport = computed(() => auth.user.value?.permissions.includes("REPORTES_EXPORTAR") ?? false);
const currentReportTitle = computed(() => tabs.find(item => item.id === tab.value)?.label ?? "Resumen general");
const tab = ref<Tab>("summary"); const error = ref(""); const optionsError = ref(""); const optionsLoading = ref(false); const exporting = ref(false);
const options = ref<ReportOptions>({ campus: [], edificios: [], tiposBeneficiario: [], condiciones: [], estadosSolicitud: [], periodos: [], estadosTarjeta: [], tiposTarjeta: [], estadosAsignacion: [], beneficiarios: [] });
const summary = ref<ReportSummary | null>(null); const summaryLoading = ref(false); const summaryExportError = ref("");
const detailedExporting = ref(""); const detailedExportError = ref("");
const summaryFilters = ref<ReportFilter>({ estado: "all", desde: "", hasta: "" });
const beneficiaryFilters = ref({ page: 1, pageSize: 10, search: "", estado: "all", idTipoBeneficiario: undefined as number | undefined, idTipoCondicion: undefined as number | undefined, desde: "", hasta: "" });
const requestFilters = ref({ page: 1, pageSize: 10, search: "", codigoEstadoSolicitud: "", idPeriodoAcademico: undefined as number | undefined, idBeneficiario: undefined as number | undefined, sinAsignacion: false, desde: "", hasta: "" });
const cardFilters = ref({ page: 1, pageSize: 10, search: "", idEstadoTarjeta: undefined as number | undefined, idTipoTarjeta: undefined as number | undefined, disponibilidad: "all", desde: "", hasta: "" });
const assignmentFilters = ref({ page: 1, pageSize: 10, search: "", estado: "all", idEstadoAsignacion: undefined as number | undefined, idBeneficiario: undefined as number | undefined, idTarjeta: undefined as number | undefined, proximasDias: 15, desde: "", hasta: "" });
const historyFilters = ref({ page: 1, pageSize: 10, idBeneficiario: undefined as number | undefined, idTarjeta: undefined as number | undefined, tipoMovimiento: "all", desde: "", hasta: "" });
const beneficiaryData = ref<Paginated<BeneficiaryReport>>({ items: [], pagination: { page: 1, pageSize: 10, total: 0, totalPages: 0 } }); const requestData = ref<Paginated<RequestReport>>({ items: [], pagination: { page: 1, pageSize: 10, total: 0, totalPages: 0 } }); const cardData = ref<Paginated<CardReport>>({ items: [], pagination: { page: 1, pageSize: 10, total: 0, totalPages: 0 } }); const assignmentData = ref<Paginated<AssignmentReport>>({ items: [], pagination: { page: 1, pageSize: 10, total: 0, totalPages: 0 } }); const historyData = ref<Paginated<HistoryReport>>({ items: [], pagination: { page: 1, pageSize: 10, total: 0, totalPages: 0 } });
const loading = ref<Record<Tab, boolean>>({ summary: false, beneficiarios: false, solicitudes: false, tarjetas: false, asignaciones: false, historial: false }); const errors = ref<Record<Tab, string>>({ summary: "", beneficiarios: "", solicitudes: "", tarjetas: "", asignaciones: "", historial: "" });
const filteredBuildings = computed(() => options.value.edificios.filter(item => !summaryFilters.value.idCampus || item.idCampus === summaryFilters.value.idCampus));
const message = (cause: unknown) => cause instanceof ApiError ? cause.message : "No fue posible cargar la reportería.";
const date = (value: string | null | undefined) => value ? new Date(value).toLocaleDateString("es-HN") : "—";
const dateTime = (value: string | null | undefined) => value ? new Date(value).toLocaleString("es-HN") : "—";
const value = (item: number | string | null | undefined) => item === null || item === undefined ? "—" : String(item);
const beneficiaryColumns: GridColumn[] = [{ key: "idBeneficiario", label: "ID", width: "8%" }, { key: "nombreCompleto", label: "Beneficiario", width: "22%" }, { key: "nombreTipoBeneficiario", label: "Tipo", width: "16%" }, { key: "nombreTipoCondicion", label: "Condición", width: "18%" }, { key: "estado", label: "Estado", width: "10%" }, { key: "fechaRegistro", label: "Registro", width: "13%" }, { key: "academico", label: "Académico", width: "18%" }];
const requestColumns: GridColumn[] = [{ key: "codigoSolicitud", label: "Solicitud", width: "12%" }, { key: "nombreBeneficiario", label: "Beneficiario", width: "20%" }, { key: "fechaSolicitud", label: "Solicitud", width: "13%" }, { key: "periodo", label: "Período", width: "14%" }, { key: "estado", label: "Estado", width: "14%" }, { key: "resolucion", label: "Resolución", width: "13%" }, { key: "asignacion", label: "Asignación", width: "14%" }];
const cardColumns: GridColumn[] = [{ key: "codigoTarjeta", label: "Tarjeta", width: "13%" }, { key: "tipo", label: "Tipo", width: "14%" }, { key: "estado", label: "Estado administrativo", width: "17%" }, { key: "disponibilidad", label: "Disponibilidad", width: "13%" }, { key: "nombreBeneficiario", label: "Beneficiario", width: "18%" }, { key: "asignacion", label: "Asignación", width: "13%" }, { key: "vigencia", label: "Vigencia", width: "18%" }];
const assignmentColumns: GridColumn[] = [{ key: "nombreBeneficiario", label: "Beneficiario", width: "19%" }, { key: "codigoTarjeta", label: "Tarjeta", width: "12%" }, { key: "codigoSolicitud", label: "Solicitud", width: "12%" }, { key: "estado", label: "Estado", width: "14%" }, { key: "inicio", label: "Inicio", width: "12%" }, { key: "fin", label: "Fin", width: "12%" }, { key: "dias", label: "Días restantes", width: "12%" }];
const historyColumns: GridColumn[] = [{ key: "tipoMovimiento", label: "Movimiento", width: "12%" }, { key: "fechaMovimiento", label: "Fecha", width: "16%" }, { key: "nombreBeneficiario", label: "Beneficiario", width: "18%" }, { key: "codigoTarjeta", label: "Tarjeta", width: "11%" }, { key: "estados", label: "Estado", width: "18%" }, { key: "usuarioResponsable", label: "Responsable", width: "15%" }, { key: "motivoCambio", label: "Motivo", width: "20%" }];
function resetPage(filters: { page: number }) { filters.page = 1; }
async function loadSummary() { summaryLoading.value = true; errors.value.summary = ""; try { summary.value = await getReportSummary(summaryFilters.value); } catch (cause) { summary.value = null; errors.value.summary = message(cause); } finally { summaryLoading.value = false; } }
async function exportCsv() { exporting.value = true; summaryExportError.value = ""; try { const blob = await downloadReportSummary(summaryFilters.value); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "reportes-siga.csv"; anchor.click(); URL.revokeObjectURL(url); } catch (cause) { summaryExportError.value = message(cause); } finally { exporting.value = false; } }
async function exportDetailed(type: DetailedReportType, format: "xlsx" | "pdf") { detailedExporting.value = `${type}:${format}`; detailedExportError.value = ""; const filters = type === "beneficiarios" ? beneficiaryFilters.value : type === "solicitudes" ? requestFilters.value : type === "tarjetas" ? cardFilters.value : type === "asignaciones" ? assignmentFilters.value : historyFilters.value; try { const blob = await downloadDetailedReport(type, format, filters); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `siga-${type}.${format}`; anchor.click(); URL.revokeObjectURL(url); } catch (cause) { detailedExportError.value = message(cause); } finally { detailedExporting.value = ""; } }
async function loadTab(target: Tab = tab.value) { if (target === "summary") return loadSummary(); loading.value[target] = true; errors.value[target] = ""; try { if (target === "beneficiarios") beneficiaryData.value = await listBeneficiaryReport(beneficiaryFilters.value); if (target === "solicitudes") requestData.value = await listRequestReport(requestFilters.value); if (target === "tarjetas") cardData.value = await listCardReport(cardFilters.value); if (target === "asignaciones") assignmentData.value = await listAssignmentReport(assignmentFilters.value); if (target === "historial") historyData.value = await listHistoryReport(historyFilters.value); } catch (cause) { errors.value[target] = message(cause); } finally { loading.value[target] = false; } }
function selectTab(next: Tab) { tab.value = next; void loadTab(next); }
async function loadOptions() { optionsLoading.value = true; optionsError.value = ""; try { options.value = await getReportOptions(); } catch (cause) { optionsError.value = message(cause); } finally { optionsLoading.value = false; } }
function beneficiaryRows() { return beneficiaryData.value.items.map(item => ({ ...item, estado: item.estadoBeneficiario ? "Activo" : "Inactivo", academico: [item.numeroCuenta, item.nombreCarrera, item.nivelAcademico].filter(Boolean).join(" · ") || "—", fechaRegistro: date(item.fechaRegistro) })); }
function requestRows() { return requestData.value.items.map(item => ({ ...item, fechaSolicitud: date(item.fechaSolicitud), periodo: item.codigoPeriodoAcademico ?? item.nombrePeriodoAcademico ?? "—", estado: `${item.codigoEstadoSolicitud} · ${item.nombreEstadoSolicitud}`, resolucion: item.fechaResolucion ? dateTime(item.fechaResolucion) : item.fechaAprobacion ? dateTime(item.fechaAprobacion) : "—", asignacion: item.tieneAsignacionVigente ? item.codigoTarjeta ?? "Asignada" : "Sin asignación" })); }
function cardRows() { return cardData.value.items.map(item => ({ ...item, tipo: item.nombreTipoTarjeta ?? item.codigoTipoTarjeta ?? "—", estado: `${item.codigoEstadoTarjeta} · ${item.nombreEstadoTarjeta}`, disponibilidad: item.disponible ? "Disponible" : "Asignada", asignacion: item.fechaAsignacion ? dateTime(item.fechaAsignacion) : "—", vigencia: item.fechaInicioVigencia ? `${date(item.fechaInicioVigencia)} — ${date(item.fechaFinVigencia)}` : "—" })); }
function assignmentRows() { return assignmentData.value.items.map(item => ({ ...item, estado: `${item.codigoEstadoAsignacion} · ${item.nombreEstadoAsignacion}`, inicio: date(item.fechaInicioVigencia), fin: date(item.fechaFinVigencia), dias: item.diasRestantes === null ? "Sin vencimiento" : value(item.diasRestantes) })); }
function historyRows() { return historyData.value.items.map(item => ({ ...item, fechaMovimiento: dateTime(item.fechaMovimiento), estados: `${item.nombreEstadoAnterior ?? "Inicio"} → ${item.nombreEstadoNuevo}`, motivoCambio: item.motivoCambio ?? "—" })); }
onMounted(() => { void loadOptions(); void loadSummary(); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Operación' }, { label: 'Reportes y Estadísticas' }]" />
  <PageHeader eyebrow="Operación" title="Reportes y Estadísticas" description="Consultas operativas de solo lectura calculadas con información persistida en SQL Server." />
  <nav class="reports-tabs" aria-label="Secciones de reportería"><button v-for="item in tabs" :key="item.id" type="button" :class="{ active: tab === item.id }" @click="selectTab(item.id)">{{ item.label }}</button></nav>
   <div v-if="optionsLoading" class="bo-form-note">Cargando catálogos de reportería...</div><div v-if="optionsError" class="bo-form-note bo-state-error">{{ optionsError }}</div><div v-if="detailedExportError" class="bo-notice alert--error">{{ detailedExportError }}</div>
   <section class="bo-card report-header"><div><span class="report-eyebrow">Reportería operativa</span><h2>{{ currentReportTitle }}</h2><p>Información calculada con los filtros seleccionados.</p></div><div class="report-header-actions"><button v-if="tab === 'summary'" type="button" class="bo-btn" :disabled="exporting || summaryLoading || !summary" @click="exportCsv">{{ exporting ? 'Exportando...' : 'Exportar CSV' }}</button><template v-else-if="canExport"><button type="button" class="bo-btn" :disabled="Boolean(detailedExporting)" @click="exportDetailed(tab as DetailedReportType, 'xlsx')">{{ detailedExporting === `${tab}:xlsx` ? 'Generando...' : 'Exportar Excel' }}</button><button type="button" class="bo-btn" :disabled="Boolean(detailedExporting)" @click="exportDetailed(tab as DetailedReportType, 'pdf')">{{ detailedExporting === `${tab}:pdf` ? 'Generando...' : 'Exportar PDF' }}</button></template></div></section>
  <template v-if="tab === 'summary'"><section class="bo-card reports-filters"><form class="bo-toolbar reports-toolbar" @submit.prevent="loadSummary"><label>Estado<select v-model="summaryFilters.estado"><option value="all">Todos</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></label><label>Campus<select v-model="summaryFilters.idCampus"><option :value="undefined">Todos los campus</option><option v-for="item in options.campus" :key="item.idCampus" :value="item.idCampus">{{ item.nombreCampus }}</option></select></label><label>Edificio<select v-model="summaryFilters.idEdificio"><option :value="undefined">Todos los edificios</option><option v-for="item in filteredBuildings" :key="item.idEdificio" :value="item.idEdificio">{{ item.nombreEdificio }}</option></select></label><label>Tipo de beneficiario<select v-model="summaryFilters.idTipoBeneficiario"><option :value="undefined">Todos los tipos</option><option v-for="item in options.tiposBeneficiario" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Desde<input v-model="summaryFilters.desde" type="date" /></label><label>Hasta<input v-model="summaryFilters.hasta" type="date" /></label><button class="bo-btn bo-btn-primary">Actualizar</button></form></section><div v-if="summaryExportError" class="bo-notice alert--error">{{ summaryExportError }}</div><div v-if="errors.summary" class="bo-state bo-state-error">{{ errors.summary }} <button class="bo-btn" @click="loadSummary">Reintentar</button></div><div v-if="summaryLoading" class="bo-state">Calculando indicadores...</div><template v-else-if="summary"><section class="reports-kpis"><article v-for="item in [{ label: 'Beneficiarios', value: summary.beneficiarios.total }, { label: 'Solicitudes', value: summary.solicitudes.total }, { label: 'Asignaciones vigentes', value: summary.asignacionesVigentes }, { label: 'Campus', value: summary.infraestructura.campus }, { label: 'Edificios', value: summary.infraestructura.edificios }, { label: 'Elevadores', value: summary.infraestructura.elevadores }, { label: 'Dispositivos', value: summary.infraestructura.dispositivos }]" :key="item.label" class="bo-card"><small>{{ item.label }}</small><strong>{{ item.value }}</strong></article></section><section class="reports-panels"><article class="bo-card reports-panel"><h2>Beneficiarios por tipo</h2><div v-if="!summary.beneficiarios.porTipo.length" class="bo-state">No hay resultados.</div><table v-else><tbody><tr v-for="item in summary.beneficiarios.porTipo" :key="item.codigoTipo"><td>{{ item.nombreTipo }}</td><td>{{ item.total }}</td></tr></tbody></table></article><article class="bo-card reports-panel"><h2>Solicitudes por estado</h2><div v-if="!summary.solicitudes.porEstado.length" class="bo-state">No hay resultados.</div><table v-else><tbody><tr v-for="item in summary.solicitudes.porEstado" :key="item.codigoEstado"><td>{{ item.nombreEstado }}</td><td>{{ item.total }}</td></tr></tbody></table></article><article class="bo-card reports-panel"><h2>Tarjetas por estado</h2><div v-if="!summary.tarjetas.porEstado.length" class="bo-state">No hay resultados.</div><table v-else><tbody><tr v-for="item in summary.tarjetas.porEstado" :key="item.codigoEstado"><td>{{ item.nombreEstado }}</td><td>{{ item.total }}</td></tr></tbody></table></article></section></template></template>
  <template v-else-if="tab === 'beneficiarios'"><section class="bo-card report-section"><form class="bo-toolbar reports-toolbar" @submit.prevent="resetPage(beneficiaryFilters); loadTab()"><label>Buscar<input v-model="beneficiaryFilters.search" placeholder="Nombre, cuenta o carné" /></label><label>Estado<select v-model="beneficiaryFilters.estado"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="inactive">Inactivos</option></select></label><label>Tipo<select v-model="beneficiaryFilters.idTipoBeneficiario"><option :value="undefined">Todos los tipos</option><option v-for="item in options.tiposBeneficiario" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Condición<select v-model="beneficiaryFilters.idTipoCondicion"><option :value="undefined">Todas las condiciones</option><option v-for="item in options.condiciones" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select></label><label>Desde<input v-model="beneficiaryFilters.desde" type="date" /></label><label>Hasta<input v-model="beneficiaryFilters.hasta" type="date" /></label><button class="bo-btn bo-btn-primary">Consultar</button></form><DataGrid :columns="beneficiaryColumns" :rows="beneficiaryRows()" :pagination="beneficiaryData.pagination" :loading="loading.beneficiarios" :error="errors.beneficiarios" :row-key="row => String(row.idBeneficiario)" @page="page => { beneficiaryFilters.page = page; loadTab() }"><template #cell-estado="{ row }"><span :class="row.estado === 'Activo' ? 'bo-status bo-status-active' : 'bo-status bo-status-inactive'">{{ row.estado }}</span></template></DataGrid></section></template>
  <template v-else-if="tab === 'solicitudes'"><section class="bo-card report-section"><form class="bo-toolbar reports-toolbar" @submit.prevent="resetPage(requestFilters); loadTab()"><label>Buscar<input v-model="requestFilters.search" placeholder="Solicitud, beneficiario o cuenta" /></label><label>Estado<select v-model="requestFilters.codigoEstadoSolicitud"><option value="">Todos los estados</option><option v-for="item in options.estadosSolicitud" :key="item.idTipoValor" :value="item.codigoTipoValor">{{ item.codigoTipoValor }} · {{ item.nombreTipoValor }}</option></select></label><label>Período<select v-model="requestFilters.idPeriodoAcademico"><option :value="undefined">Todos los períodos</option><option v-for="item in options.periodos" :key="item.idPeriodoAcademico" :value="item.idPeriodoAcademico">{{ item.codigoPeriodoAcademico }}</option></select></label><label>Beneficiario<select v-model="requestFilters.idBeneficiario"><option :value="undefined">Todos los beneficiarios</option><option v-for="item in options.beneficiarios" :key="item.idBeneficiario" :value="item.idBeneficiario">{{ item.nombreBeneficiario }}</option></select></label><label class="bo-check-label"><input v-model="requestFilters.sinAsignacion" type="checkbox" /> Sin asignación vigente</label><label>Desde<input v-model="requestFilters.desde" type="date" /></label><label>Hasta<input v-model="requestFilters.hasta" type="date" /></label><button class="bo-btn bo-btn-primary">Consultar</button></form><DataGrid :columns="requestColumns" :rows="requestRows()" :pagination="requestData.pagination" :loading="loading.solicitudes" :error="errors.solicitudes" :row-key="row => String(row.idSolicitud)" @page="page => { requestFilters.page = page; loadTab() }" /></section></template>
  <template v-else-if="tab === 'tarjetas'"><section class="bo-card report-section"><form class="bo-toolbar reports-toolbar" @submit.prevent="resetPage(cardFilters); loadTab()"><label>Buscar<input v-model="cardFilters.search" placeholder="Código, serie o beneficiario" /></label><label>Estado<select v-model="cardFilters.idEstadoTarjeta"><option :value="undefined">Todos los estados</option><option v-for="item in options.estadosTarjeta" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.codigoTipoValor }} · {{ item.nombreTipoValor }}</option></select></label><label>Disponibilidad<select v-model="cardFilters.disponibilidad"><option value="all">Toda disponibilidad</option><option value="available">Disponibles</option><option value="assigned">Asignadas</option></select></label><label>Tipo<select v-model="cardFilters.idTipoTarjeta"><option :value="undefined">Todos los tipos</option><option v-for="item in options.tiposTarjeta" :key="item.idTipoTarjeta" :value="item.idTipoTarjeta">{{ item.nombreTipoTarjeta }}</option></select></label><label>Desde<input v-model="cardFilters.desde" type="date" /></label><label>Hasta<input v-model="cardFilters.hasta" type="date" /></label><button class="bo-btn bo-btn-primary">Consultar</button></form><DataGrid :columns="cardColumns" :rows="cardRows()" :pagination="cardData.pagination" :loading="loading.tarjetas" :error="errors.tarjetas" :row-key="row => String(row.idTarjeta)" @page="page => { cardFilters.page = page; loadTab() }" /></section></template>
  <template v-else-if="tab === 'asignaciones'"><section class="bo-card report-section"><form class="bo-toolbar reports-toolbar" @submit.prevent="resetPage(assignmentFilters); loadTab()"><label>Buscar<input v-model="assignmentFilters.search" placeholder="Tarjeta, solicitud o beneficiario" /></label><label>Estado<select v-model="assignmentFilters.estado"><option value="all">Todas</option><option value="vigentes">Vigentes</option><option value="vencidas">Vencidas</option><option value="proximas">Próximas a vencer</option><option value="finalizadas">Finalizadas</option></select></label><label>Próximas (días)<input v-model.number="assignmentFilters.proximasDias" type="number" min="1" max="365" title="Días para próximas a vencer" /></label><label>Estado de asignación<select v-model="assignmentFilters.idEstadoAsignacion"><option :value="undefined">Todos los estados</option><option v-for="item in options.estadosAsignacion" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.codigoTipoValor }} · {{ item.nombreTipoValor }}</option></select></label><label>Beneficiario<select v-model="assignmentFilters.idBeneficiario"><option :value="undefined">Todos los beneficiarios</option><option v-for="item in options.beneficiarios" :key="item.idBeneficiario" :value="item.idBeneficiario">{{ item.nombreBeneficiario }}</option></select></label><label>Desde<input v-model="assignmentFilters.desde" type="date" /></label><label>Hasta<input v-model="assignmentFilters.hasta" type="date" /></label><button class="bo-btn bo-btn-primary">Consultar</button></form><DataGrid :columns="assignmentColumns" :rows="assignmentRows()" :pagination="assignmentData.pagination" :loading="loading.asignaciones" :error="errors.asignaciones" :row-key="row => String(row.idAsignacion)" @page="page => { assignmentFilters.page = page; loadTab() }" /></section></template>
  <template v-else><section class="bo-card report-section"><form class="bo-toolbar reports-toolbar" @submit.prevent="resetPage(historyFilters); loadTab()"><label>Movimiento<select v-model="historyFilters.tipoMovimiento"><option value="all">Todos los movimientos</option><option value="asignacion">Asignaciones</option><option value="solicitud">Solicitudes</option><option value="tarjeta">Tarjetas</option></select></label><label>Beneficiario<select v-model="historyFilters.idBeneficiario"><option :value="undefined">Todos los beneficiarios</option><option v-for="item in options.beneficiarios" :key="item.idBeneficiario" :value="item.idBeneficiario">{{ item.nombreBeneficiario }}</option></select></label><label>Tarjeta<input v-model="historyFilters.idTarjeta" type="number" min="1" placeholder="ID tarjeta" /></label><label>Desde<input v-model="historyFilters.desde" type="date" /></label><label>Hasta<input v-model="historyFilters.hasta" type="date" /></label><button class="bo-btn bo-btn-primary">Consultar</button></form><DataGrid :columns="historyColumns" :rows="historyRows()" :pagination="historyData.pagination" :loading="loading.historial" :error="errors.historial" :row-key="row => `${row.tipoMovimiento}-${row.idMovimiento}`" @page="page => { historyFilters.page = page; loadTab() }" /></section></template>
